enum class MemoryLevel {
    REGISTERS,        // Fastest, smallest, CPU internal
    L1_CACHE,         // Few cycles latency, dedicated per core
    L2_CACHE,         // Moderate latency, typically larger
    L3_CACHE,         // Highest cache latency, shared across cores
    MAIN_MEMORY,      // DRAM, high latency (200+ cycles)
    SECONDARY_STORAGE // Disk/SSD, highest latency (ms)
};

// Access time increases downwards
MemoryLevel current = MemoryLevel::L1_CACHE;
